<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($title) ?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>@media print{nav,.filters,.no-print{display:none!important}body{background:#fff}.container{max-width:none}}</style></head><body class="bg-light"><main class="container py-4"><nav class="mb-3"><a href="<?= base_url('reports') ?>">Reports</a> / <?= esc($title) ?></nav><h1 class="h3"><?= esc($title) ?></h1><form class="row g-2 my-3 filters"><div class="col-auto"><label class="form-label">Start Date</label><input class="form-control" type="date" name="start_date" value="<?= esc($filters['start_date']) ?>"></div><div class="col-auto"><label class="form-label">End Date</label><input class="form-control" type="date" name="end_date" value="<?= esc($filters['end_date']) ?>"></div><div class="col-auto"><label class="form-label">Branch</label><select class="form-select" name="branch_id"><option value="">All branches</option><?php foreach($branches as $branch): ?><option value="<?= esc($branch['id']) ?>" <?= $filters['branch_id']===(int)$branch['id']?'selected':'' ?>><?= esc($branch['name']) ?></option><?php endforeach ?></select></div><div class="col-auto align-self-end"><button class="btn btn-primary">Filter</button><button type="button" class="btn btn-outline-secondary" onclick="window.print()">Print Report</button></div></form><p><span class="badge text-bg-primary">Total Count: <?= number_format($totalCount) ?></span> <span class="badge text-bg-success">Total Amount: Rs. <?= number_format($totalAmount,2) ?></span></p><div class="table-responsive bg-white"><table class="table table-striped"><thead><tr><th>Date</th><th>Reference</th><th>Account</th><th>Branch</th><th>Amount (LKR)</th><th>Method</th></tr></thead><tbody><?php foreach($items as $row): ?><tr><td><?= esc($row['created_at'] ?? '') ?></td><td><?= esc($row[$recordIdColumn] ?? '') ?></td><td><?= esc($row['account_no'] ?? '—') ?></td><td><?= esc($row['branch_name'] ?? '—') ?></td><td>Rs. <?= number_format((float)($row['amount'] ?? 0),2) ?></td><td><?= esc($row['deposit_method'] ?? $row['withdrawal_method'] ?? '') ?></td></tr><?php endforeach ?><?php if(!$items): ?><tr><td colspan="6" class="text-center text-secondary">No records found.</td></tr><?php endif ?></tbody></table></div></main></body></html>
